template.inlineTemplate:
//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 LISTGRP ${instance-RACF_GROUP}
/*

step.instructions:
This step runs an inline REXX program that calls IRRXUTIL to interrogate each member of group ${instance-RACF_GROUP}.
For every user ID the report shows: - Password interval (days) - Date password was last changed - Calculated expiry date - Days remaining until expiry - WARNING flag if days remaining is less than ${instance-WARN_DAYS}
Users with NOPASSWORD or PHRASE-only authentication are noted separately.

template.inlineTemplate:
//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX 'ANDRE.REXX.EXEC(PWDRPT)' '${instance-RACF_GROUP} ${instance-WARN_DAYS}'
/*

//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD DSN=${instance-REPORT_DATASET},DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX '&&SYSUID..EXEC(PWDRPT)' '${instance-RACF_GROUP} ${instance-WARN_DAYS}'
/*
